@page "/dispatch"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@using Microsoft.AspNetCore.Authorization
@inject IShipmentService ShipmentService
@attribute [Authorize]

<PageTitle>Dispatch Dashboard</PageTitle>

<div class="container mt-4">
    <h2>Dispatch Dashboard</h2>

    <div class="row mb-3">
        <div class="col-md-4">
            <label class="form-label">Filter by Status</label>
            <select class="form-select" @bind="SelectedStatus">
                <option value="">All Statuses</option>
                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@status">@status</option>
                }
            </select>
        </div>
        <div class="col-md-4">
            <label class="form-label">Search</label>
            <input type="text" class="form-control" placeholder="Tracking # or destination..."
                   @bind="SearchTerm" @bind:event="oninput" />
        </div>
        <div class="col-md-4 d-flex align-items-end">
            <button class="btn btn-secondary" @onclick="RefreshData">🔄 Refresh</button>
        </div>
    </div>

    @if (shipments is null)
    {
        <p><em>Loading shipments...</em></p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Tracking #</th>
                        <th>Origin</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                        <th>Customer</th>
                        <th>Actions</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var shipment in FilteredShipments)
                    {
                        <tr>
                            <td><strong>@shipment.TrackingNumber</strong></td>
                            <td>@shipment.Origin</td>
                            <td>@shipment.Destination</td>
                            <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                            <td>@shipment.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                            <td>@shipment.CustomerEmail</td>
                            <td>
                                <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                        value="@shipment.Status"
                                        @onchange="(e) => UpdateStatus(shipment, e)">
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@status">@status</option>
                                    }
                                </select>
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
    }
</div>

@code {
    private List<Shipment>? shipments;
    private string SelectedStatus { get; set; } = "";
    private string SearchTerm { get; set; } = "";

    private IEnumerable<Shipment> FilteredShipments =>
        (shipments ?? [])
            .Where(s => string.IsNullOrEmpty(SelectedStatus) || s.Status.ToString() == SelectedStatus)
            .Where(s => string.IsNullOrEmpty(SearchTerm) ||
                        s.TrackingNumber.Contains(SearchTerm, StringComparison.OrdinalIgnoreCase) ||
                        s.Destination.Contains(SearchTerm, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        await RefreshData();
    }

    private async Task RefreshData()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@using Microsoft.AspNetCore.Authorization
@inject IShipmentService ShipmentService
@attribute [Authorize]

<PageTitle>Track Shipment</PageTitle>

<div class="container mt-4">
    <h2>Track Your Shipment</h2>

    <div class="row mb-4">
        <div class="col-md-6">
            <div class="input-group">
                <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-001-2026)"
                       @bind="TrackingNumber" @onkeydown="HandleKeyDown" />
                <button class="btn btn-primary" @onclick="SearchShipment">
                    🔍 Track
                </button>
            </div>
        </div>
    </div>

    @if (isSearching)
    {
        <p><em>Searching...</em></p>
    }
    else if (searched && shipment is null)
    {
        <div class="alert alert-warning">
            <strong>Not found.</strong> No shipment matches tracking number "<strong>@lastSearched</strong>".
            Please check the number and try again.
        </div>
    }
    else if (shipment is not null)
    {
        <div class="card">
            <div class="card-header bg-dark text-white">
                <h5 class="mb-0">📦 @shipment.TrackingNumber</h5>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>Description</dt>
                            <dd>@shipment.Description</dd>

                            <dt>Origin</dt>
                            <dd>@shipment.Origin</dd>

                            <dt>Destination</dt>
                            <dd>@shipment.Destination</dd>

                            <dt>Shipped Date</dt>
                            <dd>@shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>
                        </dl>
                    </div>
                    <div class="col-md-6">
                        <dl>
                            <dt>Current Status</dt>
                            <dd><span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span></dd>

                            <dt>Estimated Delivery</dt>
                            <dd class="fs-5">
                                @if (shipment.EstimatedDelivery.HasValue)
                                {
                                    <strong>@shipment.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")</strong>
                                    @if (shipment.EstimatedDelivery.Value.Date == DateTime.Today)
                                    {
                                        <span class="badge bg-success ms-2">Today!</span>
                                    }
                                    else if (shipment.EstimatedDelivery.Value.Date < DateTime.Today)
                                    {
                                        <span class="badge bg-warning text-dark ms-2">Overdue</span>
                                    }
                                }
                                else
                                {
                                    <em>Not yet determined</em>
                                }
                            </dd>
                        </dl>
                    </div>
                </div>

                <h6 class="mt-3">Shipment Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                         role="progressbar"
                         style="width: @GetProgressPercent(shipment.Status)%"
                         aria-valuenow="@GetProgressPercent(shipment.Status)"
                         aria-valuemin="0" aria-valuemax="100">
                        @shipment.Status
                    </div>
                </div>
            </div>
        </div>
    }

    <hr class="mt-4" />
    <h4>My Shipments</h4>
    <p class="text-muted">Shipments associated with your account:</p>

    @if (myShipments is null)
    {
        <p><em>Loading your shipments...</em></p>
    }
    else if (!myShipments.Any())
    {
        <p class="text-muted">No shipments found for your account.</p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-hover">
                <thead>
                    <tr>
                        <th>Tracking #</th>
                        <th>Destination</th>
                        <th>Status</th>
                        <th>Est. Delivery</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var s in myShipments)
                    {
                        <tr class="cursor-pointer" @onclick="() => ViewShipment(s.TrackingNumber)">
                            <td>@s.TrackingNumber</td>
                            <td>@s.Destination</td>
                            <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                            <td>@s.EstimatedDelivery?.ToString("MMM dd, yyyy")</td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    private string TrackingNumber { get; set; } = "";
    private string lastSearched = "";
    private Shipment? shipment;
    private List<Shipment>? myShipments;
    private bool searched;
    private bool isSearching;

    [CascadingParameter]
    private Task<Microsoft.AspNetCore.Components.Authorization.AuthenticationState>? AuthState { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (AuthState is not null)
        {
            var state = await AuthState;
            var email = state.User?.Identity?.Name;
            if (!string.IsNullOrEmpty(email))
            {
                myShipments = await ShipmentService.GetShipmentsByCustomerAsync(email);
            }
            else
            {
                myShipments = [];
            }
        }
        else
        {
            myShipments = [];
        }
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(TrackingNumber)) return;

        isSearching = true;
        searched = true;
        lastSearched = TrackingNumber.Trim();
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(lastSearched);
        isSearching = false;
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await SearchShipment();
        }
    }

    private void ViewShipment(string trackingNumber)
    {
        TrackingNumber = trackingNumber;
        _ = SearchShipment();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Exception => "bg-danger",
        ShipmentStatus.Delivered => "bg-success",
        _ => "bg-primary"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 25,
        ShipmentStatus.InTransit => 50,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Exception => 50,
        _ => 0
    };
}

