    private string TrackingNumber { get; set; } = "";
    private string lastSearched = "";
    private Shipment? shipment;
    private List<Shipment>? myShipments;
    private bool searched;
    private bool isSearching;

    [CascadingParameter]
    private Task<Microsoft.AspNetCore.Components.Authorization.AuthenticationState>? AuthState { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (AuthState is not null)
        {
            var state = await AuthState;
            var email = state.User?.Identity?.Name;
            if (!string.IsNullOrEmpty(email))
            {
                myShipments = await ShipmentService.GetShipmentsByCustomerAsync(email);
            }
            else
            {
                myShipments = [];
            }
        }
        else
        {
            myShipments = [];
        }
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(TrackingNumber)) return;

        isSearching = true;
        searched = true;
        lastSearched = TrackingNumber.Trim();
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(lastSearched);
        isSearching = false;
    }

    private async Task HandleKeyDown(Microsoft.AspNetCore.Components.Web.KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await SearchShipment();
        }
    }

    private void ViewShipment(string trackingNumber)
    {
        TrackingNumber = trackingNumber;
        _ = SearchShipment();
    }

